{"type":"运行JS代码","delay":"0","delayUnit":1,"repeatCount":1,"desc":"V39：启动时间兼容旧方案定时开始；统一格式校验","jsCode":"(function(){
function S(k,v){try{zdjl.setVar(k,v,'global');}catch(e){}}
function G(k){try{return zdjl.getVar(k,'global');}catch(e){return '';}}
function L(t){try{zdjl.appendFile('/sdcard/Download/农场总控日志/农场总控_V38定时诊断.log',new Date().toISOString()+' '+t+'\n');}catch(e){}}
S('V37_TIMER_VALID','NO');S('V37_TIMER_WAIT_SEC',0);S('V38_TIMER_DUE_MS',0);S('V40_TIMER_HUD','');S('V40_TIMER_HUD_DURATION',0);
try{
 if(String(G('FC_V32_PREFLIGHT_OK')||'')!=='YES'||['TASK','DETAIL'].indexOf(String(G('FC_V31_EXPLICIT_LAUNCH')||''))<0)throw Error('启动许可无效，请从首页开始或详细编辑临时运行入口启动');
 var raw=String(G('FC_V32_LAUNCH_JSON')||'');if(!raw)throw Error('找不到本次运行的配置快照');
 var item=JSON.parse(raw);if(item.schema!==32||!item.config)throw Error('配置快照结构无效');
 var cfg=item.config,rawMode=String(cfg['启动方式']||'立即').replace(/^\s+|\s+$/g,''),now=new Date(),seconds=0,due=0;
 var mode=({'立即':'立即','立即开始':'立即','立即启动':'立即','马上运行':'立即','定时':'定时','定时开始':'定时','定时启动':'定时'})[rawMode];
 if(!mode)throw Error('未知启动方式：'+rawMode+'（应选择立即或定时）');
 cfg['启动方式']=mode;
 item.config=cfg;S('FC_V32_LAUNCH_JSON',JSON.stringify(item));S('启动方式',mode);
 L('NORMALIZE_MODE raw='+rawMode+' normalized='+mode);
 if(mode==='定时'){
   var input=String(cfg['定时开始时间']==null?'':cfg['定时开始时间']);
   input=input.replace(/[：﹕]/g,':').replace(/[点时]/g,':').replace(/分$/,'').replace(/^\s+|\s+$/g,'');
   var mt=/^(\d{1,2}):(\d{1,2})$/.exec(input);if(!mt)throw Error('定时格式不正确：'+input+'；请填写05:30');
   var hh=Number(mt[1]),mm=Number(mt[2]);if(hh<0||hh>23||mm<0||mm>59)throw Error('定时时间超出范围：'+input);
   var at=new Date(now.getFullYear(),now.getMonth(),now.getDate(),hh,mm,0,0);
   if(now.getHours()===hh&&now.getMinutes()===mm){at=new Date(now.getTime());}else if(at.getTime()<=now.getTime())at.setDate(at.getDate()+1);
   due=at.getTime();seconds=Math.ceil((due-now.getTime())/1000);
   if(!(seconds>=0&&seconds<=90000))throw Error('定时等待长度不合法');
   function pad(x){return Number(x)<10?'0'+Number(x):String(x);}
   var leftHour=Math.floor(seconds/3600),leftMin=Math.floor((seconds%3600)/60),leftSec=seconds%60;
   var disp='⏰ '+pad(at.getMonth()+1)+'-'+pad(at.getDate())+' '+pad(hh)+':'+pad(mm)+'｜现'+pad(now.getHours())+':'+pad(now.getMinutes())+':'+pad(now.getSeconds())+'｜剩'+leftHour+':'+pad(leftMin)+':'+pad(leftSec);
   S('V40_TIMER_HUD',disp);S('V40_TIMER_HUD_DURATION',Math.max(3000,seconds*1000+1500));
   L('ARMED mode='+mode+' raw='+input+' localNow='+now.toString()+' target='+at.toString()+' sec='+seconds);
 }else if(mode==='立即'){
   L('IMMEDIATE localNow='+now.toString());
 }else{throw Error('未知启动方式：'+mode);}
 S('V38_TIMER_DUE_MS',due);S('V37_TIMER_WAIT_SEC',seconds);S('V37_TIMER_VALID','YES');
}catch(e){L('ERROR '+String(e));try{zdjl.toast('定时配置错误：'+e,6000);}catch(x){}}
})();"}
