function 取账号区数(n){
    if(n==1) return 账号1区数;
    if(n==2) return 账号2区数;
    if(n==3) return 账号3区数;
    if(n==4) return 账号4区数;
    if(n==5) return 账号5区数;
    if(n==6) return 账号6区数;
    if(n==7) return 账号7区数;
    return 账号8区数;
}

function 账号编号(token){
    var s=String(token||"").trim();
    if(!s) return 0;
    var m=s.match(/^(?:账号)?([1-8])(?:号)?$/);
    if(m) return Number(m[1]);
    for(var i=0;i<8;i++){
        if(s==String(配置名称[i]||"").trim()) return i+1;
    }
    return 0;
}

function 解析账号序列(text){
    var s=String(text||"").trim();
    var out=[];

    // 最快输入：236 = 2→3→6；47 = 4→7；632 = 6→3→2
    if(/^[1-8]+$/.test(s)){
        for(var k=0;k<s.length;k++){
            var d=Number(s.charAt(k));
            var 已有=false;
            for(var z=0;z<out.length;z++) if(out[z]==d) 已有=true;
            if(!已有) out.push(d);
        }
        return out;
    }

    // 兼容原写法：2-3-6 / 2,3,6 / 羊羊-木木
    var parts=s.split(/[\s,，、;；\-—>＞]+/);
    for(var i=0;i<parts.length;i++){
        if(!parts[i]) continue;
        var n=账号编号(parts[i]);
        if(!n) return [];
        var 重复=false;
        for(var j=0;j<out.length;j++) if(out[j]==n) 重复=true;
        if(!重复) out.push(n);
    }
    return out;
}

